import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`virtual-assistant`,heroTitle:`Meet your AI personal assistant`,heroSubtitle:`Perplexity Computer is the AI assistant that handles your admin, runs your research, and drafts your docs — automatically.`,heroCta:`Delegate my tasks`,hasInputUrl:!1,heroOverlaySteps:[`Sorting your task into admin, research, docs, and follow-up work`,`Drafting emails, summaries, documents, and next actions`,`Organizing priorities, dependencies, and handoff notes`,`Virtual assistant workflow ready for review`],generatingSteps:[`Reviewing what you described`,`Designing an agent to handle admin, research, docs, and follow-ups`,`Configuring drafts, task lists, and handoff notes across your tools`,`Setting up your assistant workflow with next actions ready to review`],featureSectionTitle:`From scattered to-do to handled workflow`,featureCardTitles:[`Connects to your work stack`,`Outputs ready to review`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Slack, Notion — Computer keeps admin, research, docs, and follow-ups moving inside the tools you already use.`,`Inbox drafts. Research summaries. Calendar follow-ups. Task lists. Handoff notes. Computer gives you a clean packet instead of another loose reminder.`],capabilitySectionTitle:`Your to-do list, done`,capabilitySectionSubtitle:`Delegate the task, step away, and come back to admin, research, docs, and follow-ups ready to review.`,capabilityCards:[{title:`Executive Assistant Tasks`,description:`Computer can triage admin work, draft replies, summarize threads, and turn messy inbox requests into clean next actions.`},{title:`Research & Docs`,description:`Computer can gather context, compare options, draft documents, and package findings into a format your team can use.`},{title:`Calendar & Follow-ups`,description:`Computer can prepare meeting notes, next-step reminders, and follow-up messages so open loops keep moving.`},{title:`Connect Your Tools`,description:`Computer can work across Gmail, Google Sheets, Slack, and Notion so assistant work lands where your day already happens.`},{title:`Remember & Learn`,description:`Computer can remember your preferred tone, recurring tasks, handoff formats, and follow-up habits so future work starts with context.`},{title:`Monitor & Alert`,description:`Computer can watch for unanswered messages, stale tasks, and missing follow-ups, then flag what needs your review.`}]});export{t as default};
